package com.sirithree.shopops.admin.benchmark.v1.dataset.stage4;
import static org.assertj.core.api.Assertions.assertThat; import java.nio.charset.StandardCharsets; import java.nio.file.Files; import java.nio.file.Path; import java.util.Set; import org.junit.jupiter.api.Test;
class RecoveryHeldOutIsolationTest { @Test void heldOutRootIdsDoNotAppearInProductionOrRecoveryEvaluatorSource() throws Exception { Set<String> heldOut=Stage4RecoveryDatasetSupport.testExclusiveRoots(); assertThat(heldOut).hasSize(6); Path repo=findRepoRoot(); var roots=java.util.stream.Stream.of(repo.resolve("shopops-admin/src/main"),repo.resolve("shopops-common/src/main"),repo.resolve("shopops-commerce-mcp-server/src/main"),repo.resolve("shopops-admin/src/test/java/com/sirithree/shopops/admin/benchmark/v1/recovery/StateConvergenceEvaluator.java")).filter(Files::exists).toList(); for(Path root:roots){ if(Files.isDirectory(root)){ try(var files=Files.walk(root)){ for(Path file:files.filter(Files::isRegularFile).toList()) check(file,heldOut); }} else check(root,heldOut); } }
 private static void check(Path file,Set<String> heldOut)throws Exception{String text=Files.readString(file,StandardCharsets.UTF_8); for(String id:heldOut) assertThat(text).as(file+" must not reference held-out root "+id).doesNotContain(id);} private static Path findRepoRoot(){Path current=Path.of(".").toAbsolutePath().normalize(); for(Path candidate=current;candidate!=null;candidate=candidate.getParent()) if(Files.isDirectory(candidate.resolve("shopops-admin"))&&Files.exists(candidate.resolve("pom.xml"))) return candidate; throw new IllegalStateException("Cannot locate ShopOps repository root");}}
